`timescale 1ns/1ps
// Self-checking testbench for i2s_loopback.
//
// The codec model behaves like the WM8731 in I2S master mode:
//   * BCLK is generated by the codec (25 MHz here so the simulation stays short),
//   * ADCLRC/DACLRC have 32-BCLK slots and change on a falling edge,
//   * data is launched on the falling edge that precedes the second rising edge
//     of the slot and sampled on rising edges, MSB first, 16 bits.
//
// Independent counters make the alignment explicit:
//   bit_ix   counts rising edges inside the slot (0 = the change edge),
//   on a falling edge the codec drives what rising edge bit_ix+1 must see.
// The PL receive path therefore takes the MSB at rising edge 1 and the LSB at
// rising edge 16, and the PL transmit path puts the MSB on the wire for rising
// edge 1 exactly the same way.
//
// The captured DACDAT stream must be bit-exact with the ADCDAT stream at a
// constant frame delay, which is the L1 latency.
module tb_i2s_loopback;
    localparam integer FRAMES     = 24;
    localparam integer FIFO_DEPTH = 2;

    reg clk_sys = 0;
    always #10 clk_sys = ~clk_sys;          // 50 MHz system domain

    reg bclk = 0;
    always #20 bclk = ~bclk;                // 25 MHz codec bit clock

    reg reset_n = 0;
    wire dacdat;

    reg  [15:0] sent_l [0:FRAMES-1];
    reg  [15:0] sent_r [0:FRAMES-1];
    reg  [15:0] rec_l  [0:FRAMES-1];
    reg  [15:0] rec_r  [0:FRAMES-1];

    // ---- codec model ------------------------------------------------------
    reg [5:0]  n_bit = 6'd31;    // bit_ix seen by the next rising edge
    reg [5:0]  p_bit = 6'd0;     // rising-edge counter (32 per slot)
    reg        adclrc = 0;
    reg        adcdat = 0;
    reg [15:0] cur_l = 0, cur_r = 0;
    integer    tx_frame = -1;    // -1 so the first complete pair is frame 0
    integer    rx_frame = -1;
    reg [15:0] cap_word = 0;

    wire dadlrc = adclrc;        // both LRCLKs are in phase on the module

    // Falling edge: prepare what the next rising edge must sample.
    always @(negedge bclk) begin
        if (n_bit == 6'd31) begin
            n_bit  <= 6'd0;
            adclrc <= ~adclrc;                     // the new slot starts now
            adcdat <= 1'b0;                        // I2S one-bit delay
            if (adclrc == 1'b1) begin              // old value 1 -> new left slot
                tx_frame <= tx_frame + 1;
                cur_l    <= sent_l[tx_frame + 1];  // both channels of frame tx_frame+1
                cur_r    <= sent_r[tx_frame + 1];
            end
        end else begin
            n_bit <= n_bit + 1'b1;
            if (n_bit <= 6'd15)
                adcdat <= adclrc ? cur_r[15 - n_bit] : cur_l[15 - n_bit];
        end
    end

    // Rising edge: sample DACDAT (MSB at bit 1, LSB at bit 16); the edge where
    // the LRCLK change is first visible carries no data bit.
    always @(posedge bclk) begin
        p_bit <= (p_bit == 6'd31) ? 6'd0 : p_bit + 1'b1;
        if (p_bit >= 6'd1 && p_bit <= 6'd16) begin
            cap_word <= {cap_word[14:0], dacdat};
            if (p_bit == 6'd16 && rx_frame >= 0 && rx_frame < FRAMES) begin
                if (adclrc == 1'b0) rec_l[rx_frame] <= {cap_word[14:0], dacdat};
                else                rec_r[rx_frame] <= {cap_word[14:0], dacdat};
            end
        end
    end

    // Track the received frame index at the start of each left slot.
    always @(negedge bclk)
        if (n_bit == 6'd31 && adclrc == 1'b1) rx_frame <= rx_frame + 1;

    // ---- DUT --------------------------------------------------------------
    wire [15:0] occ_frames, latency_cycles;
    wire [31:0] adc_frames, dac_frames, bclk_cycles;
    wire [15:0] overruns, underruns;
    wire        live;

    i2s_loopback #(.FIFO_DEPTH(FIFO_DEPTH), .STALE_CYCLES(1000)) dut (
        .clk_sys(clk_sys), .reset_n_sys(reset_n),
        .bclk(bclk), .adclrc(adclrc), .adcdat(adcdat), .dadlrc(dadlrc),
        .dacdat(dacdat),
        .occ_frames(occ_frames), .latency_cycles(latency_cycles),
        .adc_frames(adc_frames), .dac_frames(dac_frames),
        .overruns(overruns), .underruns(underruns), .bclk_cycles(bclk_cycles),
        .live(live));

    // ---- checking ---------------------------------------------------------
    integer errors = 0;
    integer i, d, best_d, ok_d;

    initial begin
        for (i = 0; i < FRAMES; i = i + 1) begin
            sent_l[i] = 16'h1000 + i * 16'd7;
            sent_r[i] = 16'h2000 + i * 16'd11;
            rec_l[i]  = 16'hDEAD;
            rec_r[i]  = 16'hDEAD;
        end

        reset_n = 0;
        repeat (10) @(negedge clk_sys);
        reset_n = 1;

        #(FRAMES * 64 * 40 + 8000);

        for (i = 0; i < 10; i = i + 1)
            $display("INFO frame %0d sent L=%04h R=%04h | rec L=%04h R=%04h",
                     i, sent_l[i], sent_r[i], rec_l[i], rec_r[i]);

        best_d = -1;
        for (d = 0; d < 8; d = d + 1) begin
            ok_d = 1;
            for (i = 4; i < FRAMES - 2; i = i + 1) begin
                if (i - d < 0) ok_d = 0;
                else if (rec_l[i] !== sent_l[i - d] || rec_r[i] !== sent_r[i - d]) ok_d = 0;
            end
            if (ok_d && best_d < 0) best_d = d;
        end

        if (best_d < 0) begin
            $display("FAIL loopback: no constant delay explains the captured stream");
            errors = errors + 1;
        end else begin
            $display("INFO loopback: bit-exact at a delay of %0d frames (%0d BCLK cycles)",
                     best_d, latency_cycles);
            // Priming costs one extra frame before the DAC starts, so the
            // steady-state delay is the FIFO depth or one frame more.
            if (best_d < FIFO_DEPTH || best_d > FIFO_DEPTH + 1) begin
                $display("FAIL loopback: delay %0d frames, expected %0d or %0d",
                         best_d, FIFO_DEPTH, FIFO_DEPTH + 1);
                errors = errors + 1;
            end
            // 64 BCLK per frame in this model; the measured L1 must match the
            // observed frame delay within one frame.
            if (latency_cycles < (best_d - 1) * 64 || latency_cycles > (best_d + 1) * 64) begin
                $display("FAIL latency_cycles=%0d does not match a %0d frame delay",
                         latency_cycles, best_d);
                errors = errors + 1;
            end
        end

        if (occ_frames !== FIFO_DEPTH[15:0]) begin
            $display("FAIL occupancy: %0d frames, expected %0d", occ_frames, FIFO_DEPTH);
            errors = errors + 1;
        end
        if (!live) begin $display("FAIL live not asserted"); errors = errors + 1; end
        if (overruns !== 16'd0) begin
            $display("FAIL overruns=%0d", overruns); errors = errors + 1;
        end
        if (underruns !== 16'd0) begin
            $display("FAIL underruns=%0d", underruns); errors = errors + 1;
        end
        if (adc_frames < 16 || dac_frames < 16) begin
            $display("FAIL counters: adc=%0d dac=%0d", adc_frames, dac_frames);
            errors = errors + 1;
        end
        if (bclk_cycles === 32'h0) begin
            $display("FAIL bclk_cycles not advancing"); errors = errors + 1;
        end

        if (errors == 0) $display("PASS_I2S_LOOPBACK");
        else             $display("FAIL_I2S_LOOPBACK errors=%0d", errors);
        $finish;
    end

    initial begin
        #500000;
        $display("FAIL_I2S_LOOPBACK timeout");
        $finish;
    end
endmodule
